INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT144-S4-Q5$batch13$, 144, 4, 5, $batch13$Flaw$batch13$, $batch13$Scholar: Recently, some religions have updated the language of their traditional texts and replaced traditional rituals with more contemporary ones. These changes have been followed by increases in attendance at places of worship affiliated with these religions. This shows that any such modernization will result in increased numbers of worshipers.$batch13$, $batch13$The scholar’s reasoning is flawed because the scholar presumes without giving sufficient justification that$batch13$, $batch13$C$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=144 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q5$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$not every religion can update its texts and replace its traditional rituals$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$modernization of religious texts and rituals will not involve an alteration of their messages$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$the modernization of the texts and rituals of some religions was the cause of their increases in attendance$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$making texts and rituals more modern is the only way in which a religion could bring about an increase in attendance at places of worship$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$the growth in attendance at places of worship affiliated with religions that made their texts and rituals more modern is irreversible$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Any modernization of religious texts and rituals will increase attendance.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Some religions modernized their texts and rituals, and attendance at their places of worship then rose.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The attendance increase came after the changes. That doesn't show the changes caused it. Something else could explain the rise. The conclusion also leaps from "some religions" to "any such modernization".$batch13$), (3, $batch13$Goal$batch13$, $batch13$The scholar assumes the modernization caused the attendance increase.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT144-S4-Q5$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The scholar doesn't assume anything about what every religion can do.$batch13$), ($batch13$B$batch13$, $batch13$Whether the messages change isn't part of the argument.$batch13$), ($batch13$C$batch13$, $batch13$"Followed by" is only timing. The scholar treats it as cause without ruling out other explanations.$batch13$), ($batch13$D$batch13$, $batch13$The scholar says modernization is enough to raise attendance, not that it's the only way.$batch13$), ($batch13$E$batch13$, $batch13$The scholar assumes nothing about whether the increase will last.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT144-S4-Q5$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
